import{_ as p,a0 as o,w as s,s as d,ao as r,I as n,x as e,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Inkscape - 开源适量图形编辑器 | LCTT x X-CMD","titleTemplate":false,"description":"Inkscape - 开源适量图形编辑器 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Inkscape - 开源适量图形编辑器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Inkscape - 开源适量图形编辑器 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150409 Install Inkscape - Open Source Vector Graphic Editor","title":"Inkscape - 开源适量图形编辑器","tag":"201505","desc":""},"relativePath":"201505/20150409 Install Inkscape - Open Source Vector Graphic Editor.md","filePath":"[post].md"}'),u={name:"201505/20150409 Install Inkscape - Open Source Vector Graphic Editor.md"};function k(h,a,c,m,I,P){const l=o("Link");return s(),d("div",null,[a[19]||(a[19]=r('<h1 id="inkscape-开源适量图形编辑器" tabindex="-1">Inkscape - 开源适量图形编辑器 <a class="header-anchor" href="#inkscape-开源适量图形编辑器" aria-label="Permalink to “Inkscape - 开源适量图形编辑器”">​</a></h1><p>Inkscape是一款开源矢量图形编辑工具，并不同于Xara X、Corel Draw和Adobe Illustrator等竞争对手，它使用的是可缩放矢量图形(SVG)图形格式。SVG是一个广泛部署、免版税使用的图形格式，由W3C SVG工作组开发和维护。这是一个跨平台工具，完美运行于Linux、Windows和Mac OS上。</p><p>Inkscape始于2003年，起初它的bug跟踪系统托管于Sourceforge上，但是后来迁移到了Launchpad上。当前它最新的一个稳定版本是0.91，它不断地在发展和修改中。我们将在本文里了解一下它的突出特点和安装过程。</p><h3 id="显著特性" tabindex="-1">显著特性 <a class="header-anchor" href="#显著特性" aria-label="Permalink to “显著特性”">​</a></h3><p>让我们直接来了解这款应用程序的显著特性。</p><h4 id="创建对象" tabindex="-1">创建对象 <a class="header-anchor" href="#创建对象" aria-label="Permalink to “创建对象”">​</a></h4><ul><li>用铅笔工具来画出不同颜色、大小和形状的手绘线，用贝塞尔曲线（笔式）工具来画出直线和曲线，通过书法工具来应用到手写的书法笔画上等等</li><li>用文本工具来创建、选择、编辑和格式化文本。在纯文本框、在路径上或在形状里操作文本</li><li>方便绘制各种形状，像矩形、椭圆形、圆形、弧线、多边形、星形和螺旋形等等并调整其大小、旋转并修改（圆角化）它们</li><li>用简单地命令创建并嵌入位图</li></ul><h4 id="对象处理" tabindex="-1">对象处理 <a class="header-anchor" href="#对象处理" aria-label="Permalink to “对象处理”">​</a></h4><ul><li>通过交互式操作和调整参量来扭曲、移动、测量、旋转目标</li><li>可以对 Z 轴进行提升或降低操作。</li><li>通过对象组合和取消组合可以创建一个虚拟层用来编辑或处理</li><li>图层采用层次结构树的结构，并且能锁定或以各式各样的处理方式来重新布置</li><li>分布与对齐指令</li></ul><h4 id="填充与边框" tabindex="-1">填充与边框 <a class="header-anchor" href="#填充与边框" aria-label="Permalink to “填充与边框”">​</a></h4><ul><li>可以复制/粘贴不同风格</li><li>取色工具</li><li>用RGB, HSL, CMS, CMYK和色盘这四种不同的方式选色</li><li>渐变层编辑器能创建和管理多停点渐变层</li><li>使用图像或其它选择区作为花纹填充</li><li>用一些预定义点状花纹进行笔触填充</li><li>通过路径标示器标示开始、对折和结束点</li></ul><h4 id="路径上的操作" tabindex="-1">路径上的操作 <a class="header-anchor" href="#路径上的操作" aria-label="Permalink to “路径上的操作”">​</a></h4><ul><li>节点编辑：移动节点和贝塞尔曲线控制点，节点的对齐和分布等等</li><li>布尔运算（是或否）</li><li>运用可变的路径起迄点可简化路径</li><li>路径插入和增设连同动态和链接偏移对象</li><li>通过路径追踪把位图图像转换成路径(彩色或单色路径）</li></ul><h4 id="文本处理" tabindex="-1">文本处理 <a class="header-anchor" href="#文本处理" aria-label="Permalink to “文本处理”">​</a></h4><ul><li>所有安装好的框线字体都能用，甚至可以从右至左对齐对象</li><li>格式化文本、调整字母间距、行间距或列间距</li><li>路径上和形状上的文本中的文本、路径或形状都可以被编辑和修改</li></ul><h4 id="渲染" tabindex="-1">渲染 <a class="header-anchor" href="#渲染" aria-label="Permalink to “渲染”">​</a></h4><ul><li>Inkscape完全支持抗锯齿显示，这是一种通过柔化边界上的像素从而减少或消除凹凸锯齿的技术。</li><li>支持alpha透明显示和PNG格式图片的导出</li></ul><h3 id="在ubuntu-14-04和14-10上安装inkscape" tabindex="-1">在Ubuntu 14.04和14.10上安装Inkscape <a class="header-anchor" href="#在ubuntu-14-04和14-10上安装inkscape" aria-label="Permalink to “在Ubuntu 14.04和14.10上安装Inkscape”">​</a></h3>',18)),n("p",null,[a[1]||(a[1]=e("为了在Ubuntu上安装Inkscape，我们首先需要 ",-1)),t(l,{href:"https://launchpad.net/~inkscape.dev/+archive/ubuntu/stable"},{default:i(()=>[...a[0]||(a[0]=[e("添加它的稳定版Personal Package Archive",-1)])]),_:1}),a[2]||(a[2]=e(" (PPA) 至Advanced Package Tool (APT) 库中。打开终端并运行一下命令来添加它的PPA：",-1))]),a[20]||(a[20]=r(`<pre><code> sudo add-apt-repository ppa:inkscape.dev/stable
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/PPA-Inkscape.png" alt="PPA Inkscape"></p><p>PPA添加到APT库中后，我们要用以下命令进行更新：</p><pre><code> sudo apt-get update
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Update-APT2.png" alt="Update APT"></p><p>更新好库之后，我们准备用以下命令来完成安装：</p><pre><code> sudo apt-get install inkscape
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Install-Inkscape.png" alt="Install Inkscape"></p><p>恭喜，现在Inkscape已经被安装好了，我们可以充分利用它的丰富功能特点来编辑制作图像了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Inkscape-Main1.png" alt="Inkscape Main"></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3>`,11)),n("p",null,[a[4]||(a[4]=e("Inkscape是一款特点鲜明的图形编辑工具，它给予用户充分发挥自己艺术能力的权利。它还是一款自由安装和自定义的开源应用，并且支持各种文件类型，包括JPEG, PNG, GIF和PDF及更多。访问它的 ",-1)),t(l,{href:"https://inkscape.org/en/"},{default:i(()=>[...a[3]||(a[3]=[e("官方网站",-1)])]),_:1}),a[5]||(a[5]=e(" 来获取更多新闻和应用更新。",-1))]),a[21]||(a[21]=n("hr",null,null,-1)),n("p",null,[a[7]||(a[7]=e("via: ",-1)),t(l,{href:"http://linoxide.com/tools/install-inkscape-open-source-vector-graphic-editor/"},{default:i(()=>[...a[6]||(a[6]=[e("http://linoxide.com/tools/install-inkscape-open-source-vector-graphic-editor/",-1)])]),_:1})]),n("p",null,[a[11]||(a[11]=e("作者：",-1)),t(l,{href:"http://linoxide.com/author/arunrz/"},{default:i(()=>[...a[8]||(a[8]=[e("Aun Raza",-1)])]),_:1}),a[12]||(a[12]=e(" 译者：",-1)),t(l,{href:"https://github.com/ZTinoZ"},{default:i(()=>[...a[9]||(a[9]=[e("ZTinoZ",-1)])]),_:1}),a[13]||(a[13]=e(" 校对：",-1)),t(l,{href:"https://github.com/wxy"},{default:i(()=>[...a[10]||(a[10]=[e("wxy",-1)])]),_:1})]),n("p",null,[a[16]||(a[16]=e("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[14]||(a[14]=[e("LCTT",-1)])]),_:1}),a[17]||(a[17]=e(" 原创翻译，",-1)),t(l,{href:"http://linux.cn/"},{default:i(()=>[...a[15]||(a[15]=[e("Linux中国",-1)])]),_:1}),a[18]||(a[18]=e(" 荣誉推出",-1))])])}const x=p(u,[["render",k]]);export{T as __pageData,x as default};
